from z3 import *

def solve_bibd():
    v = 16
    b = 60
    r = 15
    k = 4
    lam = 3

    # Create the matrix variables
    X = [[Bool(f"x_{i}_{j}") for j in range(b)] for i in range(v)]

    solver = Solver()

    # Row sums
    for i in range(v):
        solver.add(Sum([If(X[i][j], 1, 0) for j in range(b)]) == r)

    # Column sums
    for j in range(b):
        solver.add(Sum([If(X[i][j], 1, 0) for i in range(v)]) == k)

    # Pairwise inner products
    for i1 in range(v):
        for i2 in range(i1 + 1, v):
            solver.add(Sum([If(And(X[i1][j], X[i2][j]), 1, 0) for j in range(b)]) == lam)

    if solver.check() == sat:
        model = solver.model()
        result = []
        for i in range(v):
            for j in range(b):
                result.append(1 if model.evaluate(X[i][j]) else 0)
        return result
    else:
        return None

