            s.add_clause([var(i, j, v) for i in range(n)])
            for i1 in range(n):
                for i2 in range(i1 + 1, n):
                    s.add_clause([-var(i1, j, v), -var(i2, j, v)])
    for i in range(n):
        s.add_clause([var(i, i, i)])
    for i in range(n):
        for j in range(n):
            for k in range(n):
                for l in range(n):
                    s.add_clause([-var(i, j, k), -var(j, i, l), var(k, l, i)])
    if s.solve():
        model = s.get_model()
        res = [0] * (n * n)
        for i in range(n):
            for j in range(n):
                for v in range(n):
                    if model[var(i, j, v) - 1] > 0:
                        res[i * n + j] = v
        return res
    else:
        return None

